import torch


def run(x):
    return torch.acosh(x)


def gen_inputs(ctx, device):
    # acosh domain is [1, inf), so generate input in [1, 2]
    shape = ctx["x__shape"]
    dtype_name = ctx["x__dtype"]
    dtype = getattr(torch, dtype_name) if isinstance(dtype_name, str) else dtype_name
    x = torch.empty(shape, dtype=dtype, device=device).uniform_(1.0, 2.0)
    return {"x": x}
